// Bar Chart Race — Animation, route: jsx
// Source: bar-chart-race
//
// Self-contained: every local import is inlined below. Requires only d3, motion, react.
// Generated by scripts/build-exemplars.mjs — edit src/gallery/, not this file.

import { useEffect, useMemo, useState } from 'react';
import * as d3 from 'd3';
import { motion, AnimatePresence } from 'motion/react';

// ---- inlined from barChartRace ----
type BrandValue = { name: string; sector: string; value: number; rank: number };
type RaceFrame = { label: string; values: BrandValue[] };

/** [name, sector, base, rise, riseMid, fall, fallMid, phase] */
type Spec = [string, string, number, number, number, number, number, number];

/** Brand names are real; the $M values are synthetic logistic curves, not Interbrand figures. */
const SPECS: Spec[] = [
  ['Coca-Cola', 'Beverages', 72500, 5000, 4, 15000, 13, 0.0],
  ['Microsoft', 'Technology', 70000, 75000, 15, 40000, 7, 0.7],
  ['IBM', 'Technology', 53000, 33000, 8, 60000, 15, 1.4],
  ['GE', 'Industrial', 42000, 12000, 3, 32000, 12, 2.1],
  ['Nokia', 'Technology', 30000, 15000, 5, 44000, 11, 2.8],
  ['Intel', 'Technology', 33000, 10000, 4, 25000, 13, 3.5],
  ["McDonald's", 'Food', 26000, 20000, 10, 6000, 16, 4.2],
  ['Disney', 'Media', 24000, 22000, 13, 0, 0, 4.9],
  ['Cisco', 'Technology', 20000, 12000, 3, 8000, 14, 5.6],
  ['Toyota', 'Automotive', 16000, 34000, 7, 0, 0, 0.35],
  ['Mercedes-Benz', 'Automotive', 17000, 33000, 12, 0, 0, 1.05],
  ['BMW', 'Automotive', 13000, 29000, 11, 0, 0, 1.75],
  ['Nike', 'Apparel', 8000, 26000, 12, 0, 0, 2.45],
  ['Louis Vuitton', 'Luxury', 6000, 27000, 10, 0, 0, 3.15],
  ['Samsung', 'Technology', 5000, 55000, 9, 0, 0, 3.85],
  ['Apple', 'Technology', 4000, 230000, 14, 0, 0, 4.55],
  ['Google', 'Technology', 3000, 165000, 12, 0, 0, 5.25],
  ['Amazon', 'Retail', 1000, 130000, 17, 0, 0, 5.95]
];

const START_YEAR = 2000;
const SPAN = 19;
const SUBSTEPS = 10;

const logistic = (t: number, mid: number) => 1 / (1 + Math.exp(-0.45 * (t - mid)));

function valueAt(spec: Spec, t: number): number {
  const [, , base, rise, riseMid, fall, fallMid, phase] = spec;
  const trend = base + rise * logistic(t, riseMid) - fall * logistic(t, fallMid);
  return Math.max(500, trend * (1 + 0.035 * Math.sin(0.85 * t + phase)));
}

function frameAt(t: number): RaceFrame {
  const values = SPECS.map((spec) => ({
    name: spec[0],
    sector: spec[1],
    value: valueAt(spec, t),
    rank: 0
  }));
  values.sort((a, b) => b.value - a.value);
  values.forEach((d, i) => (d.rank = i));
  return { label: String(START_YEAR + Math.floor(t)), values };
}

/** Sub-year interpolation is what lets bars cross the moment their values cross. */
const raceFrames: RaceFrame[] = Array.from(
  { length: SPAN * SUBSTEPS + 1 },
  (_, i) => frameAt(i / SUBSTEPS)
);

const raceSectors: string[] = Array.from(new Set(SPECS.map((s) => s[1])));

const MARGIN = { top: 26, right: 10, bottom: 10, left: 10 };
const TOP_N = 12;
const STEP_MS = 100;

/** One ranked frame per time step, plus the sectors the bars are colored by. */
export type Data = {
  frames: { label: string; values: { name: string; sector: string; value: number; rank: number }[] }[];
  sectors: string[];
};

const DEMO: Data = { frames: raceFrames, sectors: raceSectors };

const formatValue = d3.format(',d');
const formatTick = d3.format('~s');

export default function BarChartRace({ data = DEMO, width }: { data?: Data; width: number }) {
  const rowHeight = Math.max(18, Math.min(34, width / 28));
  const barHeight = rowHeight * 0.84;
  const trackHeight = rowHeight * TOP_N;
  const height = Math.round(MARGIN.top + trackHeight + MARGIN.bottom);
  const innerWidth = Math.max(0, width - MARGIN.left - MARGIN.right);

  const [index, setIndex] = useState(0);

  useEffect(() => {
    const id = window.setInterval(
      () => setIndex((i) => (i + 1) % data.frames.length),
      STEP_MS
    );
    return () => window.clearInterval(id);
  }, [data]);

  const frame = data.frames[index];
  const bars = useMemo(() => frame.values.slice(0, TOP_N), [frame]);

  const x = useMemo(
    () =>
      d3
        .scaleLinear()
        .domain([0, bars[0]?.value ?? 1])
        .range([0, innerWidth]),
    [bars, innerWidth]
  );

  const color = useMemo(
    () =>
      d3
        .scaleOrdinal<string, string>()
        .domain(data.sectors)
        .range([...d3.schemeObservable10]),
    [data]
  );

  const ticks = useMemo(
    () => x.ticks(Math.max(2, Math.round(innerWidth / 150))).filter((v) => v > 0),
    [x, innerWidth]
  );

  if (width === 0) return null;

  const ease = { duration: STEP_MS / 1000, ease: 'linear' } as const;

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label="Animated bar chart race of the twelve most valuable global brands, 2000 to 2019"
    >
      <g transform={`translate(${MARGIN.left},${MARGIN.top})`}>
        <g className="axis">
          {ticks.map((v) => (
            <g key={v} transform={`translate(${x(v)},0)`}>
              <line className="grid" y1={0} y2={trackHeight} />
              <text y={-9} textAnchor="middle">
                {formatTick(v)}
              </text>
            </g>
          ))}
        </g>

        <text
          x={innerWidth}
          y={trackHeight - rowHeight * 0.5}
          textAnchor="end"
          fill="var(--text)"
          fillOpacity={0.32}
          fontSize={rowHeight * 1.6}
          fontWeight={700}
          style={{ fontVariantNumeric: 'tabular-nums' }}
        >
          {frame.label}
        </text>

        <AnimatePresence>
          {bars.map((d) => {
            const barWidth = Math.max(1, x(d.value));
            const inside = barWidth > rowHeight * 3.4;
            return (
              <motion.g
                key={d.name}
                initial={{ y: d.rank * rowHeight, opacity: 0 }}
                animate={{ y: d.rank * rowHeight, opacity: 1 }}
                exit={{ opacity: 0 }}
                transition={ease}
              >
                <motion.rect
                  y={0}
                  height={barHeight}
                  rx={2}
                  fill={color(d.sector)}
                  fillOpacity={0.72}
                  initial={{ width: barWidth }}
                  animate={{ width: barWidth }}
                  transition={ease}
                />
                <motion.g
                  initial={{ x: barWidth }}
                  animate={{ x: barWidth }}
                  transition={ease}
                >
                  <text
                    x={inside ? -8 : 8}
                    y={barHeight / 2}
                    dy="-0.35em"
                    textAnchor={inside ? 'end' : 'start'}
                    fill="var(--text)"
                    fontSize={rowHeight * 0.42}
                    fontWeight={600}
                  >
                    {d.name}
                  </text>
                  {/* white, not --muted: the grey vanishes against the lighter sector fills */}
                  <text
                    x={inside ? -8 : 8}
                    y={barHeight / 2}
                    dy="0.95em"
                    textAnchor={inside ? 'end' : 'start'}
                    fill="#fff"
                    fillOpacity={0.78}
                    fontSize={rowHeight * 0.34}
                    style={{ fontVariantNumeric: 'tabular-nums' }}
                  >
                    {formatValue(d.value)}
                  </text>
                </motion.g>
              </motion.g>
            );
          })}
        </AnimatePresence>
      </g>
    </svg>
  );
}
